from pathlib import Path
program = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    strokes = []

    directions = {
        1: (-1, 2),
        2: (0, -4),
        3: (3, 0),
        6: (-6, 0),
    }
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in directions:
                continue
            dr, dc = directions[color]
            er, ec = r + dr, c + dc
            if not (0 <= er < h and 0 <= ec < w):
                continue
            path = []
            if color == 1:
                path = [(r, c + 1), (r, c + 2)]
            elif dc:
                step = 1 if dc > 0 else -1
                path = [(r, c + k) for k in range(step, dc, step)]
            else:
                step = 1 if dr > 0 else -1
                path = [(r + k, c) for k in range(step, dr, step)]
            for pr, pc in path:
                if 0 <= pr < h and 0 <= pc < w:
                    out[pr][pc] = 5
            out[er][ec] = color
            strokes.append(set((pr, pc) for pr, pc in path if 0 <= pr < h and 0 <= pc < w))

    crossings = set()
    for i in range(len(strokes)):
        for j in range(i + 1, len(strokes)):
            crossings.update(strokes[i] & strokes[j])
    for r, c in crossings:
        out[r][c] = 4
    for r, c in crossings:
        rr, cc = r + 1, c - 1
        while 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
'''
